arguments.command:
# Try with function symbols (T/t type)
DBG=/tmp/symbols/dbg/libmonosgen-2.0.so.dbg

nm -C "$DBG" 2>/dev/null | grep ' [tTwW] ' | sort | awk '
{
  addr = strtonum("0x" $1)
  name = $3
  if (addr <= 0x2f4b20) { f1_addr = addr; f1_name = name }
  if (addr <= 0x2f4c84) { f2_addr = addr; f2_name = name }
  if (addr <= 0x2c1a40) { f3_addr = addr; f3_name = name }
}
END {
  printf "0x2f4b20 in: %s (base 0x%x, offset +0x%x)\n", f1_name, f1_addr, 0x2f4b20-f1_addr
  printf "0x2f4c84 in: %s (base 0x%x, offset +0x%x)\n", f2_name, f2_addr, 0x2f4c84-f2_addr
  printf "0x2c1a40 in: %s (base 0x%x, offset +0x%x)\n", f3_name, f3_addr, 0x2c1a40-f3_addr
}'

